function backup(file) {
  const dest = `${file}.backup-condicion-motor-generico`;
  if (!fs.existsSync(dest)) {
    fs.copyFileSync(file, dest);
  }
}

function replaceOnce(text, regex, replacement, label) {
  const matches = text.match(regex);
  if (!matches) {
    throw new Error(`No encontré el bloque: ${label}`);
  }
  return text.replace(regex, replacement);
}

function replaceLiteralOnce(text, before, after, label) {
  const idx = text.indexOf(before);
  if (idx < 0) {
    throw new Error(`No encontré el texto: ${label}`);
  }
  return text.slice(0, idx) + after + text.slice(idx + before.length);
}

